def solve(data):
    packages = data.get("packages", {})
    roots = data.get("roots", {})
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = set(data.get("features", []))
    names = sorted(packages)

    def eligible(name, interval=None):
        return options(
            packages.get(name, []), interval, blocked.get(name, ()), pins.get(name)
        )

    def intersect(current, lower, upper):
        lo, hi = current
        if lower is not None:
            lo = lower if lo is None else max(lo, lower)
        if upper is not None:
            hi = upper if hi is None else min(hi, upper)
        if lo is not None and hi is not None and lo > hi:
            return False, current
        return True, (lo, hi)

    constraints = {}
    for name, interval in roots.items():
        if name not in packages or not isinstance(interval, (list, tuple)) or len(interval) < 2:
            return {"error": "unsatisfiable"}
        ok, bounds = intersect((None, None), interval[0], interval[1])
        if not ok:
            return {"error": "unsatisfiable"}
        constraints[name] = bounds

    best_versions = None
    best_score = None

    def is_acyclic(selected_rows):
        graph = {
            name: [dep for dep, _, _ in dependency_constraints(row, features)]
            for name, row in selected_rows.items()
        }
        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for dependency in graph.get(name, ()):
                if dependency in graph and not visit(dependency):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def search(assigned, limits, selected_rows):
