                return

        pending = set(limits) - set(assigned)
        if not pending:
            if not is_acyclic(selected_rows):
                return
            score = tuple(assigned.get(name, -1) for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = dict(assigned)
            return

        choices = {}
        for name in pending:
            rows = eligible(name, limits[name])
            if not rows:
                return
            choices[name] = rows
