                    valid = False
                    break
                if dep_name in next_assigned:
                    dep_version = next_assigned[dep_name]
                    if ((bounds[0] is not None and dep_version < bounds[0]) or
                            (bounds[1] is not None and dep_version > bounds[1])):
                        valid = False
                        break
                next_limits[dep_name] = bounds

            if valid:
                search(next_assigned, next_limits, next_selected_rows)

    search({}, constraints, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": {name: best_versions[name] for name in sorted(best_versions)}}
