    if interval is None:
        lower, upper = None, None
    else:
        lower, upper = interval

    eligible = [
        row for row in rows
        if (lower is None or lower <= row["version"])
        and (upper is None or row["version"] <= upper)
        and row["version"] not in blocked
        and (pin is None or row["version"] == pin)
    ]
    return sorted(eligible, key=lambda row: row["version"], reverse=True)


def dependency_constraints(row, features=()):
    result = []
    for dependency in row.get("deps", []):
        if isinstance(dependency, str):
            result.append((dependency, None, None))
        elif isinstance(dependency, dict):
            feature = dependency.get("feature")
            if feature and feature not in features:
                continue
            name = dependency.get("name", dependency.get("package"))
            if isinstance(name, str):
                result.append((name, dependency.get("min"), dependency.get("max")))
        elif (isinstance(dependency, (list, tuple)) and dependency
              and isinstance(dependency[0], str)):
            lower = dependency[1] if len(dependency) > 1 else None
            upper = dependency[2] if len(dependency) > 2 else None
            result.append((dependency[0], lower, upper))
    return result


def dependencies(row, features=()):
    return {name for name, _, _ in dependency_constraints(row, features)}
